SELECT cars_data.Year, AVG(cars_data.Weight) as Average_Weight
FROM cars_data
GROUP BY cars_data.Year;

SELECT Model 
FROM car_names 
WHERE MakeId IN (
    SELECT Id 
    FROM cars_data 
    WHERE Weight < (
        SELECT AVG(Weight) 
        FROM cars_data
    )
);

SELECT s.Song_Name 
FROM singer s 
WHERE s.Age > (SELECT AVG(Age) FROM singer);

SELECT s.Name, s.Country
FROM singer s
WHERE s.Song_Name LIKE '%Hey%';

SELECT Document_Name, Template_ID 
FROM Documents 
WHERE Document_Description LIKE '%w%';

SELECT email_address 
FROM Professionals 
WHERE state IN ('HI', 'WI');

SELECT COUNT(*) 
FROM Owners 
WHERE owner_id NOT IN (SELECT owner_id FROM Dogs WHERE abandoned_yn = 'N');

SELECT e.City, COUNT(*) as Number_of_employees
FROM employee e
GROUP BY e.City;

SELECT AVG(Num_of_Staff) 
FROM museum 
WHERE Open_Year < '2009';

SELECT student_id, COUNT(*) as likes_count
FROM Likes
GROUP BY student_id;

SELECT Record_Company, COUNT(*) as Number_of_Orchestras
FROM orchestra
GROUP BY Record_Company;

SELECT conductor.Name, orchestra.Orchestra
FROM conductor
JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;

SELECT o.Record_Company, COUNT(o.Orchestra_ID) as Number_of_Orchestras
FROM orchestra o
GROUP BY o.Record_Company;

SELECT PetType, AVG(pet_age) as Average_Age, MAX(pet_age) as Maximum_Age
FROM Pets
GROUP BY PetType;

SELECT COUNT(*) FROM Has_Pet 
JOIN Student ON Has_Pet.StuID = Student.StuID 
WHERE Student.Age > 20;

SELECT PetType, AVG(weight) as AverageWeight
FROM Pets
GROUP BY PetType;

SELECT StuID, COUNT(PetID) as Number_of_Pets
FROM Has_Pet
GROUP BY StuID;

SELECT Money_Rank 
FROM poker_player 
WHERE Earnings = (SELECT MAX(Earnings) FROM poker_player);

SELECT p.property_type_code, rpt.property_type_description
FROM Properties p
JOIN Ref_Property_Types rpt ON p.property_type_code = rpt.property_type_code;

SELECT Citizenship, COUNT(*) as Number_of_Singers
FROM singer
GROUP BY Citizenship;

SELECT cell_mobile_number 
FROM Students 
WHERE first_name = 'Timmothy' AND last_name = 'Ward';

SELECT contestant_name 
FROM CONTESTANTS 
WHERE contestant_name != 'Jessie Alloway';

SELECT p.first_name, p.birth_date
FROM players p
WHERE p.country_code = 'USA';
